WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), reading_ts) days_since_reading_ts FROM device_readings WHERE humidity BETWEEN 41 AND 73), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM filtered), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, SUM(CASE WHEN device_code = 'DV-02' THEN humidity ELSE 0 END) AS dv_02_humidity, MIN(reading_ts) AS first_reading_ts, ROUND(SUM(days_since_reading_ts) / NULLIF(COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END), 0), 2) AS days_since_reading_ts_per_dv_01, BIT_AND(status_bits) AS status_bits_bit_and, MIN(is_new_burst) AS min_is_new_burst, APPROX_PERCENTILE(days_since_reading_ts, ARRAY(0.25, 0.5, 0.75)) AS days_since_reading_ts_quartiles FROM islands GROUP BY activity_day HAVING dv_02_humidity >= 0
